 534	export class UiActionStore {
 535	  constructor(
 536	    private readonly database: AsyncSqlDatabase,
 537	    private readonly clock: RepositoryClock = systemClock,
 538	  ) {}
 539	
 540	  getJournal(documentId: string): Promise<UiActionJournal> {
 541	    if (!isContractId(documentId)) return Promise.reject(new Error("OpenUI document id is invalid."));
 542	    return withExclusiveTransaction(this.database, (transaction) => readUiActionJournal(transaction, documentId));
 543	  }
 544	
 545	  dispatch(
 546	    action: UiAction,
 547	    sourceDocument: UiDocument,
 548	    mutation: UiActionMutation,
 549	  ): Promise<UiActionResult> {
 550	    if (!validateUiActionAgainstDocument(action, sourceDocument)) {
 551	      return Promise.reject(new Error("This OpenUI action does not apply to the current document revision."));
 552	    }
 553	    return withExclusiveTransaction(this.database, async (transaction) => {
 554	      const journal = await readUiActionJournal(transaction, action.documentId);
 555	      const existing = receiptForUiAction(journal, action);
 556	      if (existing) {
 557	        if (!existing.result) throw new Error("A pending OpenUI action must be recovered before replay.");
 558	        return structuredClone(existing.result);
 559	      }
 560	
 561	      const now = this.clock();
 562	      const current = await readData(transaction, now);
 563	      const candidate = mutation(structuredClone(current), now);
 564	      const next = { ...candidate.data, generatedAt: now };
 565	      await replaceData(transaction, next);
 566	
 567	      const result: UiActionResult = {
 568	        schemaVersion: UI_CONTRACT_VERSION,
 569	        documentId: action.documentId,
 570	        sourceRevision: action.documentRevision,
 571	        actionIdempotencyKey: action.idempotencyKey,
 572	        status: "completed",
 573	        documentLifecycle: candidate.resultingDocument.lifecycle,
 574	        resultingDocument: candidate.resultingDocument,
 575	        ...(candidate.message === undefined ? {} : { message: candidate.message }),
 576	      };
 577	      if (!validateUiActionResult(result)) throw new Error("OpenUI action produced an invalid completion result.");
 578	
 579	      const nextJournal: UiActionJournal = {
 580	        ...journal,
 581	        receipts: [...journal.receipts, {
 582	          schemaVersion: UI_CONTRACT_VERSION,
 583	          action: structuredClone(action),
 584	          actionFingerprint: canonicalUiAction(action),
 585	          state: "completed",
 586	          createdAt: now,
 587	          updatedAt: now,
 588	          result: structuredClone(result),
 589	        }],
 590	      };
 591	      if (!validateUiActionJournal(nextJournal)) throw new Error("OpenUI action journal quota or validation failed.");
 592	      await transaction.runAsync(
 593	        `INSERT INTO ui_action_journals (document_id, updated_at, payload_json) VALUES (?, ?, ?)
 594	         ON CONFLICT(document_id) DO UPDATE SET updated_at = excluded.updated_at, payload_json = excluded.payload_json;`,
 595	        action.documentId,
 596	        now,
 597	        JSON.stringify(nextJournal),
 598	      );
 599	      return result;
 600	    });
 601	  }
 602	}
