 133	/**
 134	 * Split assistant text into Markdown and OpenUI programs.
 135	 *
 136	 * An opening fence produces a segment immediately, but only whole top-level
 137	 * statements are committed to the renderer. Existing Markdown and legacy
 138	 * `<keating-*>` tags remain untouched in text segments.
 139	 */
 140	export function parseOpenUIMessageSegments(text: string, documentScope = ""): OpenUIMessageSegment[] {
 141		const segments: OpenUIMessageSegment[] = [];
 142		let cursor = 0;
 143		OPENUI_FENCE.lastIndex = 0;
 144		let match: RegExpExecArray | null;
 145	
 146		while ((match = OPENUI_FENCE.exec(text)) !== null) {
 147			if (match.index > cursor) {
 148				segments.push({ type: "text", content: text.slice(cursor, match.index) });
 149			}
 150	
 151			const bodyStart = OPENUI_FENCE.lastIndex;
 152			const closing = findClosingFence(text, bodyStart);
 153			const bodyEnd = closing?.index ?? text.length;
 154			const rawProgram = text.slice(bodyStart, bodyEnd);
 155			const metadata = parseMetadata(match[1], rawProgram, match.index, documentScope);
 156			const trimmed = rawProgram.trim();
 157			if (trimmed.startsWith("{")) {
 158				let document: UiDocument | undefined;
 159				let error: string | undefined;
 160				if (closing) {
 161					try {
 162						const candidate: unknown = JSON.parse(trimmed);
 163						if (!validateUiDocument(candidate)) throw new Error("The OpenUI JSON document does not satisfy the learner contract.");
 164						document = candidate;
 165					} catch (cause) {
 166						error = cause instanceof Error ? cause.message : "The OpenUI JSON document is invalid.";
 167					}
 168				}
 169				segments.push({ type: "openui", format: "document", program: "", rawProgram, complete: closing !== null, ...(document ? { document } : {}), ...(error ? { error } : {}), metadata });
 170			} else {
 171				segments.push({
 172					type: "openui",
 173					format: "source",
 174					program: committedOpenUIProgram(rawProgram, closing !== null),
 175					rawProgram,
 176					complete: closing !== null,
 177					metadata,
 178				});
 179			}
 180	
 181			if (!closing) {
 182				cursor = text.length;
 183				break;
 184			}
 185			cursor = closing.end;
 145			...(optionalText(link.detail) !== undefined ? { detail: text(link.detail) } : {}),
 146		};
 147	}
