 149	function mapElement(element: ElementNode, index: number): UiDocumentNode[] {
 150		const id = elementId(element, `openui-node-${index + 1}`);
 151		const props = element.props;
 152		switch (element.typeName) {
 153			case "Explanation": {
 154				const title = optionalText(props.title);
