 157			case "Callout": return [{ type: "callout", id, markdown: text(props.markdown), tone: text(props.tone, "info") as "info" | "hint" | "check" | "warning", ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
 158			case "Question": return Array.isArray(props.questions) ? props.questions.map((entry, questionIndex) => ({ type: "question", ...question(id, entry, questionIndex) })) : [];
 159			case "Quiz": return [{ type: "quiz", id: contractId(text(props.id, id), id), title: text(props.topic, "Quiz"), questions: Array.isArray(props.questions) ? props.questions.map((entry, questionIndex) => question(id, entry, questionIndex, true)) : [] }];
