 167			case "StudyPlan": return [{
 168				type: "study-plan", id: contractId(text(props.id, id), id), title: text(props.title, "Study plan"),
 169				...(optionalText(props.overview) ? { overview: text(props.overview) } : {}),
 170				items: Array.isArray(props.items) ? props.items.map((entry, itemIndex) => planItem(entry, itemIndex, id)) : [],
 171				...(Array.isArray(props.relatedPlans) ? { relatedPlans: props.relatedPlans.map(planLink) } : {}),
 172			}];
 173			case "ConceptMap": return [{ type: "concept-map", id, source: text(props.code), ...(optionalText(props.title) ? { title: text(props.title) } : {}) }];
 174			case "LearningImage": return [{ type: "image", id, alt: text(props.alt, "Learning image"), resource: { id: childId(id, "resource"), title: text(props.title, "Learning image"), format: "uri", uri: text(props.src) } }];
 175			case "LearningAnimation": return [{ type: "handoff", id, target: "web", reason: text(props.summary, `Open the ${text(props.topic, "learning")} animation in Keating web`), context: "The source interaction contains executable HTML, so the portable learner contract records an explicit trusted-surface handoff instead of embedding or executing it." }];
