 181	/** Compile the browser OpenUI language into the versioned cross-surface contract. */
 182	export function compileOpenUISourceToSharedDocument(source: string, options: CompileSharedOpenUIOptions): UiDocument {
 183		const result = parser.parse(source);
 184		if (!result.root || result.root.typeName !== "LearningSurface") throw new Error("OpenUI source has no LearningSurface root.");
 185		if (result.meta.incomplete || result.root.partial) throw new Error("OpenUI source is incomplete.");
 186		if (result.meta.errors.length || result.meta.unresolved.length) throw new Error("OpenUI source contains invalid or unresolved components.");
 187		const content = result.root.props.content;
 188		if (!Array.isArray(content) || !content.every((entry) => record(entry).type === "element")) throw new Error("OpenUI LearningSurface content is invalid.");
 189		const at = options.updatedAt ?? options.createdAt ?? new Date().toISOString();
 190		const document: UiDocument = {
 191			schemaVersion: UI_CONTRACT_VERSION,
 192			id: contractId(options.documentId, "openui-document"),
 193			revision: options.revision ?? 0,
 194			lifecycle: "ready",
 195			supportedSurfaces: ["web", "desktop", "mobile", "terminal"],
 196			...(optionalText(result.root.props.title) ? { title: text(result.root.props.title) } : {}),
 197			...(optionalText(result.root.props.description) ? { description: text(result.root.props.description) } : {}),
 198			nodes: content.flatMap((entry, index) => mapElement(entry as ElementNode, index)),
 199			createdAt: options.createdAt ?? at,
 200			updatedAt: at,
 201		};
 202		if (!validateUiDocument(document)) throw new Error("Compiled OpenUI document does not satisfy the shared learner contract.");
 203		return document;
 204	}

