import { useState } from "react";
import type { UiAction, UiDocument, UiDocumentNode, UiQuestion, UiStudyPlanItem } from "@keating/learner-contracts";
import { css } from "../../../styled-system/css";
import { MarkdownBlock } from "../../components/MarkdownBlock";
import { MermaidRenderer } from "../../components/MermaidRenderer";

export interface SharedUiActionEvent {
	type: UiAction["type"];
	humanFriendlyMessage: string;
	params: Record<string, unknown>;
}

const panel = css({ marginBlock: "0.75rem", display: "grid", gap: "0.75rem", border: "1px solid var(--border)", borderRadius: "0.75rem", background: "var(--background)", padding: "1rem" });
const section = css({ display: "grid", gap: "0.625rem", borderTop: "1px solid var(--border)", paddingTop: "0.75rem", _first: { borderTop: "none", paddingTop: 0 } });
const button = css({ minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", paddingInline: "0.75rem", fontSize: "0.8125rem", fontWeight: 600, cursor: "pointer", _hover: { background: "var(--muted)" }, _focusVisible: { outline: "2px solid var(--ring)", outlineOffset: "2px" } });
const input = css({ width: "100%", minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", background: "var(--background)", padding: "0.625rem", color: "var(--foreground)" });

export function SharedUiDocumentRenderer({ document, onAction }: { document: UiDocument; onAction?: (event: SharedUiActionEvent) => void }) {
	const interactive = document.lifecycle === "ready" && document.supportedSurfaces.includes("web");
	return <section className={panel} data-shared-openui-document={document.id} data-openui-revision={document.revision}>
		{document.title ? <h3 className={css({ fontSize: "1rem", fontWeight: 700 })}>{document.title}</h3> : null}
		{document.description ? <p className={css({ color: "var(--muted-foreground)", fontSize: "0.8125rem" })}>{document.description}</p> : null}
		{!interactive ? <div role="status" className={css({ border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.75rem", color: "var(--muted-foreground)" })}>
			This interaction is {document.lifecycle.replace("_", " ")}. Its content remains available, but controls are disabled until a durable retry restores a ready revision.
		</div> : null}
		{document.nodes.map((node) => <SharedNode key={node.id} node={node} disabled={!interactive} onAction={onAction} />)}
	</section>;
}

function SharedNode({ node, disabled, onAction }: { node: UiDocumentNode; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	if (node.type === "markdown") return <div className={section}><MarkdownBlock content={node.markdown} /></div>;
	if (node.type === "callout") return <aside className={css({ display: "grid", gap: "0.625rem", borderTop: "1px solid var(--border)", borderLeft: "3px solid var(--primary)", paddingTop: "0.75rem", paddingLeft: "0.75rem" })} data-callout-tone={node.tone}>
		<strong>{node.title ?? node.tone}</strong><MarkdownBlock content={node.markdown} />
	</aside>;
	if (node.type === "question") return <Question node={node} disabled={disabled} onAction={onAction} />;
	if (node.type === "quiz") return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4>{node.questions.map((question) => <Question key={question.id} node={question} disabled={disabled} onAction={onAction} />)}</div>;
	if (node.type === "goal") return <Checklist title={node.title} nodeId={node.id} items={node.steps.map((step) => ({ id: step.id, title: step.title, done: step.status === "done" }))} actionType="complete-goal-step" disabled={disabled} onAction={onAction} />;
	if (node.type === "deck") return <Deck node={node} disabled={disabled} onAction={onAction} />;
	if (node.type === "study-plan") return node.items ? <Plan nodeId={node.id} title={node.title ?? "Study plan"} overview={node.overview} items={node.items} disabled={disabled} onAction={onAction} /> : <Resource title={node.resource?.title ?? "Study plan"} content={node.resource?.content} uri={node.resource?.uri} />;
	if (node.type === "artifact") return <Resource title={node.resource.title} content={node.resource.content} uri={node.resource.uri} markdown={node.resource.format === "markdown"} />;
	if (node.type === "concept-map") return <div className={section}>{node.title ? <h4 className={css({ fontWeight: 700 })}>{node.title}</h4> : null}<MermaidRenderer content={node.source} /></div>;
	if (node.type === "notes") return <Notes node={node} disabled={disabled} onAction={onAction} />;
	if (node.type === "image") return <figure className={section}><img src={node.resource.uri} alt={node.alt} className={css({ maxWidth: "100%", borderRadius: "0.5rem" })} /><figcaption>{node.resource.title}</figcaption></figure>;
	if (node.type === "media") return <Media node={node} />;
	return <div className={section}><strong>Continue on {node.target}</strong><p>{node.reason}</p><p className={css({ color: "var(--muted-foreground)" })}>{node.context}</p>{node.target === "web" ? <a className={button} href="/">Open Keating web</a> : null}</div>;
}

function Question({ node, disabled, onAction }: { node: UiQuestion; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [answer, setAnswer] = useState("");
	const [selected, setSelected] = useState<string[]>([]);
	const [rowSelections, setRowSelections] = useState<string[]>(() => node.items?.map(() => "") ?? []);
	const [rowReasons, setRowReasons] = useState<string[]>(() => node.items?.map(() => "") ?? []);
	const blankCount = node.blanks?.length ?? (node.prompt.match(/_{3,}|\{\{blank\}\}/g)?.length ?? 0);
	const [blankAnswers, setBlankAnswers] = useState<string[]>(() => Array.from({ length: blankCount }, () => ""));
	const multiple = node.multiSelect || node.kind === "multi_select";
	const rows = node.kind === "classification" || node.kind === "matching";
	const blanks = node.kind === "blanks" || node.kind === "fill_in";
	const payload = rows
		? (node.items ?? []).map((item, index) => ({ item, optionId: rowSelections[index] ?? "", ...(node.requireReasons ? { reason: rowReasons[index] ?? "" } : {}) }))
		: blanks ? blankAnswers : node.choices ? selected : answer;
	const ready = rows
		? rowSelections.length > 0 && rowSelections.every(Boolean) && (!node.requireReasons || rowReasons.every((reason) => reason.trim().length > 0))
		: blanks ? blankAnswers.length > 0 && blankAnswers.every((entry) => entry.trim().length > 0)
			: node.choices ? selected.length > 0 : answer.trim().length > 0;
	const submit = () => onAction?.(node.choices && !rows
		? { type: "choose-option", humanFriendlyMessage: `Answered: ${node.prompt}`, params: { nodeId: node.id, optionIds: selected } }
		: { type: "submit-answer", humanFriendlyMessage: `Answered: ${node.prompt}`, params: { nodeId: node.id, answer: payload } });
	return <fieldset className={section} data-question-kind={node.kind ?? "text"}>
		<legend className={css({ fontWeight: 650 })}>{node.header ?? node.prompt}</legend>
		{node.header ? <p>{node.prompt}</p> : null}
		{rows ? <div className={css({ display: "grid", gap: "0.75rem" })}>{node.items?.map((item, rowIndex) => <div key={`${node.id}-${rowIndex}`} className={css({ display: "grid", gap: "0.375rem", border: "1px solid var(--border)", borderRadius: "0.5rem", padding: "0.625rem" })}>
			<strong>{item}</strong>
			<select disabled={disabled} className={input} aria-label={`${node.choiceLabel ?? "Choice"} for ${item}`} value={rowSelections[rowIndex]} onChange={(event) => setRowSelections((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))}><option value="">Select…</option>{node.choices?.map((choice) => <option key={choice.id} value={choice.id} disabled={node.kind === "matching" && node.uniqueMatches !== false && rowSelections.some((selected, index) => index !== rowIndex && selected === choice.id)}>{choice.label}</option>)}</select>
			{node.requireReasons ? <input disabled={disabled} className={input} aria-label={`${node.reasonLabel ?? "Reason"} for ${item}`} value={rowReasons[rowIndex]} onChange={(event) => setRowReasons((current) => current.map((value, index) => index === rowIndex ? event.currentTarget.value : value))} placeholder={node.reasonLabel ?? "Reason"} /> : null}
		</div>)}</div>
			: blanks ? <div className={css({ display: "grid", gap: "0.375rem" })}>{blankAnswers.map((value, index) => <input disabled={disabled} key={`${node.id}-blank-${index}`} className={input} aria-label={`Blank ${index + 1}`} value={value} onChange={(event) => setBlankAnswers((current) => current.map((entry, entryIndex) => entryIndex === index ? event.currentTarget.value : entry))} placeholder={node.blanks?.[index]?.placeholder ?? `Blank ${index + 1}`} />)}</div>
				: node.choices ? <div className={css({ display: "grid", gap: "0.375rem" })}>{node.choices.map((choice) => <label key={choice.id} className={css({ display: "flex", alignItems: "center", gap: "0.5rem" })}><input disabled={disabled} type={multiple ? "checkbox" : "radio"} name={node.id} checked={selected.includes(choice.id)} onChange={() => setSelected((current) => multiple ? current.includes(choice.id) ? current.filter((id) => id !== choice.id) : [...current, choice.id] : [choice.id])} />{choice.label}</label>)}</div>
					: node.kind === "slider" ? <div className={css({ display: "grid", gap: "0.375rem" })}><input disabled={disabled} type="range" min={node.min ?? 0} max={node.max ?? 100} step={node.step ?? 1} value={answer || node.min || 0} onChange={(event) => setAnswer(event.currentTarget.value)} /><output>{answer || node.min || 0}</output></div>
						: <textarea disabled={disabled} className={input} value={answer} onChange={(event) => setAnswer(event.currentTarget.value)} placeholder="Type your answer" />}
		{node.hint ? <small>{node.hint}</small> : null}
		<button className={button} type="button" disabled={disabled || !ready} onClick={submit}>Submit answer</button>
	</fieldset>;
}

function Checklist({ title, nodeId, items, actionType, disabled, onAction }: { title: string; nodeId: string; items: Array<{ id: string; title: string; done: boolean }>; actionType: "complete-goal-step" | "complete-plan-item"; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [done, setDone] = useState(() => new Set(items.filter((item) => item.done).map((item) => item.id)));
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{items.map((item) => <label key={item.id} className={css({ display: "flex", gap: "0.5rem" })}><input disabled={disabled} type="checkbox" checked={done.has(item.id)} onChange={() => { const next = new Set(done); next.has(item.id) ? next.delete(item.id) : next.add(item.id); setDone(next); onAction?.(actionType === "complete-goal-step" ? { type: actionType, humanFriendlyMessage: `${next.has(item.id) ? "Completed" : "Reopened"}: ${item.title}`, params: { nodeId, stepId: item.id } } : { type: actionType, humanFriendlyMessage: `${next.has(item.id) ? "Completed" : "Reopened"}: ${item.title}`, params: { nodeId, itemId: item.id, completed: next.has(item.id) } }); }} />{item.title}</label>)}</div>;
}

function Plan({ nodeId, title, overview, items, disabled, onAction }: { nodeId: string; title: string; overview?: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{overview ? <MarkdownBlock content={overview} /> : null}<PlanItems nodeId={nodeId} items={items} disabled={disabled} onAction={onAction} /></div>;
}

function PlanItems({ nodeId, items, disabled, onAction }: { nodeId: string; items: UiStudyPlanItem[]; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	return <ul className={css({ display: "grid", gap: "0.5rem", paddingLeft: "1rem" })}>{items.map((item) => <li key={item.id}><Checklist title={item.title} nodeId={nodeId} items={[{ id: item.id, title: item.detail ?? item.title, done: item.status === "done" }]} actionType="complete-plan-item" disabled={disabled} onAction={onAction} />{item.children ? <PlanItems nodeId={nodeId} items={item.children} disabled={disabled} onAction={onAction} /> : null}</li>)}</ul>;
}

function Notes({ node, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "notes" }>; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [value, setValue] = useState(node.value);
	return <div className={section}><label htmlFor={node.id} className={css({ fontWeight: 700 })}>{node.title}</label><textarea disabled={disabled} id={node.id} className={input} value={value} placeholder={node.placeholder} onChange={(event) => setValue(event.currentTarget.value)} /><button disabled={disabled} className={button} type="button" onClick={() => onAction?.({ type: "update-notes", humanFriendlyMessage: `Updated ${node.title}`, params: { nodeId: node.id, value } })}>Save notes</button></div>;
}

function Deck({ node, disabled, onAction }: { node: Extract<UiDocumentNode, { type: "deck" }>; disabled: boolean; onAction?: (event: SharedUiActionEvent) => void }) {
	const [index, setIndex] = useState(0);
	const [revealed, setRevealed] = useState(false);
	const card = node.cards[index];
	if (!card) return <div className={section}>This deck has no cards.</div>;
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4><button disabled={disabled} className={button} type="button" onClick={() => setRevealed((value) => !value)}>{revealed ? card.back : card.front}</button>{revealed ? <div className={css({ display: "flex", flexWrap: "wrap", gap: "0.375rem" })}>{["Again", "Hard", "Good", "Easy"].map((label, rating) => <button disabled={disabled} key={label} className={button} type="button" onClick={() => { onAction?.({ type: "rate-card", humanFriendlyMessage: `${label}: ${card.front}`, params: { nodeId: node.id, cardId: card.id, rating } }); setRevealed(false); setIndex((index + 1) % node.cards.length); }}>{label}</button>)}</div> : null}</div>;
}

function Resource({ title, content, uri, markdown = false }: { title: string; content?: string; uri?: string; markdown?: boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{content ? markdown ? <MarkdownBlock content={content} /> : <pre className={css({ overflowX: "auto", whiteSpace: "pre-wrap" })}>{content}</pre> : null}{uri ? <a className={button} href={uri} target="_blank" rel="noreferrer">Open resource</a> : null}</div>;
}

function Media({ node }: { node: Extract<UiDocumentNode, { type: "media" }> }) {
	if (node.kind === "audio") return <div className={section}><strong>{node.resource.title}</strong><audio controls src={node.resource.uri} /></div>;
	if (node.kind === "video") return <div className={section}><strong>{node.resource.title}</strong><video controls src={node.resource.uri} className={css({ maxWidth: "100%" })} /></div>;
	return <Resource title={node.resource.title} uri={node.resource.uri} content="Animation opens only from its validated resource URL." />;
}
import {
	createContext,
	useCallback,
	useContext,
	useMemo,
	useState,
	type ReactNode,
} from "react";
import type { UiDocument } from "@keating/learner-contracts";
import {
	Renderer,
	type ActionEvent,
	type OpenUIError,
} from "@openuidev/react-lang";
import { CircleAlert, Loader2 } from "lucide-react";
import { css } from "../../../styled-system/css";
import type { StorageLike as EventStoreStorage } from "../event-store";
import { keatingOpenUILibrary } from "./library";
import type {
	KeatingOpenUIAction,
	OpenUIDocumentMetadata,
} from "./types";
import { SharedUiDocumentRenderer } from "./shared-renderer";

const STATE_KEY_PREFIX = "keating:openui-state:v1:";

interface StoredOpenUIState {
	version: 1;
	updatedAt: number;
	state: Record<string, unknown>;
}

type StorageLike = Pick<EventStoreStorage, "getItem" | "setItem">;

export type KeatingOpenUIActionHandler = (action: KeatingOpenUIAction) => void;

const OpenUIActionContext = createContext<KeatingOpenUIActionHandler | null>(null);

export function KeatingOpenUIActionProvider({
	onAction,
	children,
}: {
	onAction: KeatingOpenUIActionHandler;
	children: ReactNode;
}) {
	return <OpenUIActionContext.Provider value={onAction}>{children}</OpenUIActionContext.Provider>;
}

export function openUIStateKey(documentId: string): string {
	return `${STATE_KEY_PREFIX}${documentId}`;
}

export function loadOpenUIState(
	storage: StorageLike | null,
	metadata: OpenUIDocumentMetadata,
): Record<string, unknown> {
	if (!storage || metadata.lifecycle === "ephemeral") return {};
	try {
		const raw = storage.getItem(openUIStateKey(metadata.id));
		if (!raw) return {};
		const parsed = JSON.parse(raw) as Partial<StoredOpenUIState>;
		return parsed.version === 1 && parsed.state && typeof parsed.state === "object"
			? parsed.state
			: {};
	} catch {
		return {};
	}
}

export function saveOpenUIState(
	storage: StorageLike | null,
	metadata: OpenUIDocumentMetadata,
	state: Record<string, unknown>,
): boolean {
	if (!storage || metadata.lifecycle === "ephemeral") return false;
	try {
		const payload: StoredOpenUIState = { version: 1, updatedAt: Date.now(), state };
		storage.setItem(openUIStateKey(metadata.id), JSON.stringify(payload));
		return true;
	} catch {
		return false;
	}
}

function browserStorage(): StorageLike | null {
	if (typeof window === "undefined") return null;
	try {
		return window.localStorage;
	} catch {
		return null;
	}
}

export function KeatingOpenUIRenderer({
	program,
	document,
	metadata,
	isStreaming = false,
}: {
	program?: string;
	document?: UiDocument;
	metadata: OpenUIDocumentMetadata;
	isStreaming?: boolean;
}) {
	const hostAction = useContext(OpenUIActionContext);
	const [errors, setErrors] = useState<OpenUIError[]>([]);
	const storage = useMemo(browserStorage, []);
	const initialState = useMemo(
		() => loadOpenUIState(storage, metadata),
		[storage, metadata.id, metadata.lifecycle],
	);

	const handleAction = useCallback(
		(event: ActionEvent) => {
			const action: KeatingOpenUIAction = {
			const action: KeatingOpenUIAction = {
				type: event.type,
				humanFriendlyMessage: event.humanFriendlyMessage,
				params: event.params,
				formState: event.formState,
				formName: event.formName,
				document: metadata,
			};
			hostAction?.(action);
		},
		[hostAction, metadata],
	);

	const handleStateUpdate = useCallback(
		(state: Record<string, unknown>) => {
			saveOpenUIState(storage, metadata, state);
		},
		[storage, metadata],
	);

	return (
		<div
			data-openui-document={metadata.id}
			data-openui-lifecycle={metadata.lifecycle}
			data-openui-revision={metadata.revision}
			aria-busy={isStreaming}
		>
			{isStreaming ? (
				<div className={css({ marginBottom: "0.375rem", display: "flex", alignItems: "center", gap: "0.375rem", fontSize: "0.6875rem", color: "var(--muted-foreground)" })} role="status">
					<Loader2 aria-hidden="true" size={12} className={css({ animation: "spin 1s linear infinite", "@media (prefers-reduced-motion: reduce)": { animation: "none" } })} />
					Building interaction
				</div>
			) : null}
			{document ? <SharedUiDocumentRenderer document={document} onAction={(event) => hostAction?.({ ...event, document: metadata })} /> : program ? (
				<div className={isStreaming ? css({ pointerEvents: "none", opacity: 0.78 }) : undefined}>
					<Renderer
						response={program}
						library={keatingOpenUILibrary}
						isStreaming={isStreaming}
						initialState={initialState}
						onAction={handleAction}
						onStateUpdate={handleStateUpdate}
						onError={setErrors}
					/>
				</div>
			) : null}
			{!isStreaming && errors.length > 0 ? (
				<div className={css({ marginBlock: "0.75rem", display: "flex", alignItems: "flex-start", gap: "0.5rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">
					<CircleAlert aria-hidden="true" size={15} className={css({ marginTop: "0.0625rem", flexShrink: 0 })} />
					<span>This interaction could not be rendered completely. The surrounding lesson is still available.</span>
				</div>
			) : null}
		</div>
	);
}
 *
 * An opening fence produces a segment immediately, but only whole top-level
 * statements are committed to the renderer. Existing Markdown and legacy
 * `<keating-*>` tags remain untouched in text segments.
 */
export function parseOpenUIMessageSegments(text: string, documentScope = ""): OpenUIMessageSegment[] {
	const segments: OpenUIMessageSegment[] = [];
	let cursor = 0;
	OPENUI_FENCE.lastIndex = 0;
	let match: RegExpExecArray | null;

	while ((match = OPENUI_FENCE.exec(text)) !== null) {
		if (match.index > cursor) {
			segments.push({ type: "text", content: text.slice(cursor, match.index) });
		}

		const bodyStart = OPENUI_FENCE.lastIndex;
		const closing = findClosingFence(text, bodyStart);
		const bodyEnd = closing?.index ?? text.length;
		const rawProgram = text.slice(bodyStart, bodyEnd);
		const metadata = parseMetadata(match[1], rawProgram, match.index, documentScope);
		const trimmed = rawProgram.trim();
		if (trimmed.startsWith("{")) {
			let document: UiDocument | undefined;
			let error: string | undefined;
			if (closing) {
				try {
					const candidate: unknown = JSON.parse(trimmed);
					if (!validateUiDocument(candidate)) throw new Error("The OpenUI JSON document does not satisfy the learner contract.");
					const scoped = { ...candidate, id: metadata.id, revision: metadata.revision };
					if (!validateUiDocument(scoped)) throw new Error("The scoped OpenUI JSON document does not satisfy the learner contract.");
					document = scoped;
				} catch (cause) {
					error = cause instanceof Error ? cause.message : "The OpenUI JSON document is invalid.";
				}
			}
			segments.push({ type: "openui", format: "document", program: "", rawProgram, complete: closing !== null, ...(document ? { document } : {}), ...(error ? { error } : {}), metadata });
		} else {
			segments.push({
				type: "openui",
				format: "source",
				program: committedOpenUIProgram(rawProgram, closing !== null),
				rawProgram,
				complete: closing !== null,
				metadata,
			});
		}

		if (!closing) {
			cursor = text.length;
			break;
		}
		cursor = closing.end;
		OPENUI_FENCE.lastIndex = cursor;
	}

	if (cursor < text.length) segments.push({ type: "text", content: text.slice(cursor) });
	if (segments.length === 0) segments.push({ type: "text", content: text });
	return segments;
}

/** Remove OpenUI source from text copied from an assistant message. */
export function stripOpenUIPrograms(text: string): string {
	return parseOpenUIMessageSegments(text)
		.filter((segment): segment is Extract<OpenUIMessageSegment, { type: "text" }> => segment.type === "text")
		.map((segment) => segment.content)
		.join("")
		.trim();
}

